import{_ as a,o as s,c as d,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 11 章 文件与目录：整理、搜索、批量处理","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 11 章 文件与目录：整理、搜索、批量处理.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 11 章 文件与目录：整理、搜索、批量处理.md"}'),n={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 11 章 文件与目录：整理、搜索、批量处理.md"};function o(l,t,r,i,p,h){return s(),d("div",null,[...t[0]||(t[0]=[e(`<h1 id="第-11-章-文件与目录-整理、搜索、批量处理" tabindex="-1">第 11 章 文件与目录：整理、搜索、批量处理 <a class="header-anchor" href="#第-11-章-文件与目录-整理、搜索、批量处理" aria-label="Permalink to &quot;第 11 章 文件与目录：整理、搜索、批量处理&quot;">​</a></h1><blockquote><p>本章目标：掌握文件类任务的三板斧——整理、搜索、批量处理，以及批量操作的安全规程。<strong>文件任务的精髓是&quot;先看清楚，再动手，动完留痕&quot;。批量操作不怕慢，就怕不可逆。</strong></p></blockquote><h2 id="_11-1-场景-文件越堆越多-找东西越来越难" tabindex="-1">11.1 场景：文件越堆越多，找东西越来越难 <a class="header-anchor" href="#_11-1-场景-文件越堆越多-找东西越来越难" aria-label="Permalink to &quot;11.1 场景：文件越堆越多，找东西越来越难&quot;">​</a></h2><p>电脑里的文件越堆越多，找东西越来越难。文件类任务包括三大类：</p><table tabindex="0"><thead><tr><th>类别</th><th>说明</th><th>典型例子</th></tr></thead><tbody><tr><td><strong>整理</strong></td><td>归档、重命名、统一格式</td><td>整理下载目录、批量重命名</td></tr><tr><td><strong>搜索</strong></td><td>按文件名找、按内容找</td><td>找某个报告、搜某段代码</td></tr><tr><td><strong>批量处理</strong></td><td>成百上千个文件的统一操作</td><td>全部转码、统一加头注释</td></tr></tbody></table><h2 id="_11-2-找文件-用对工具" tabindex="-1">11.2 找文件：用对工具 <a class="header-anchor" href="#_11-2-找文件-用对工具" aria-label="Permalink to &quot;11.2 找文件：用对工具&quot;">​</a></h2><h3 id="_11-2-1-工具对照表" tabindex="-1">11.2.1 工具对照表 <a class="header-anchor" href="#_11-2-1-工具对照表" aria-label="Permalink to &quot;11.2.1 工具对照表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>需求</th><th>工具</th><th>示例</th></tr></thead><tbody><tr><td>按文件名/扩展名找</td><td>Glob</td><td><code>**/*.md</code> 找所有 Markdown</td></tr><tr><td>按内容找</td><td>Grep</td><td>搜 &quot;TODO&quot; 或函数名</td></tr><tr><td>看目录结构</td><td>目录列表</td><td>了解项目布局</td></tr><tr><td>看文件内容</td><td>Read</td><td>读具体文件</td></tr></tbody></table><h3 id="_11-2-2-黄金法则" tabindex="-1">11.2.2 黄金法则 <a class="header-anchor" href="#_11-2-2-黄金法则" aria-label="Permalink to &quot;11.2.2 黄金法则&quot;">​</a></h3><blockquote><p><strong>找文件用 Glob，搜内容用 Grep。</strong></p></blockquote><p>不要让我用命令行的 find/grep 绕路——专用工具更快、更安全、更好追踪。</p><p><strong>两者的关键区别：</strong></p><table tabindex="0"><thead><tr><th></th><th>Glob（按名找）</th><th>Grep（按内容找）</th></tr></thead><tbody><tr><td>找什么</td><td>文件名/路径</td><td>文件里的文字</td></tr><tr><td>典型问题</td><td>&quot;项目里有哪些 .md 文件？&quot;</td><td>&quot;这个报错出现在哪些文件？&quot;</td></tr><tr><td>使用场景</td><td>盘点资源</td><td>定位问题</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">组合技巧</p><p><strong>先用 Glob 缩小范围，再用 Grep 精确搜索。</strong> 比如：&quot;先在 src/ 下找所有 .py（Glob），再在结果里搜 &#39;user_id&#39;（Grep）&quot;——两步就把问题范围从全项目缩小到几个文件。</p></div><h2 id="_11-3-案例-整理一个混乱的下载目录" tabindex="-1">11.3 案例：整理一个混乱的下载目录 <a class="header-anchor" href="#_11-3-案例-整理一个混乱的下载目录" aria-label="Permalink to &quot;11.3 案例：整理一个混乱的下载目录&quot;">​</a></h2><h3 id="_11-3-1-指令" tabindex="-1">11.3.1 指令 <a class="header-anchor" href="#_11-3-1-指令" aria-label="Permalink to &quot;11.3.1 指令&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>整理 downloads/ 目录：</span></span>
<span class="line"><span>- 图片 → 按年月归档到 photos/2026-08/</span></span>
<span class="line"><span>- 文档 → 按类型归档到 docs/{pdf,word,sheet}/</span></span>
<span class="line"><span>- 其他 → 移到 archive/</span></span>
<span class="line"><span>先给出整理计划（会移动哪些文件），我确认后再执行。</span></span></code></pre></div><h3 id="_11-3-2-我的做法-逐步拆解" tabindex="-1">11.3.2 我的做法（逐步拆解） <a class="header-anchor" href="#_11-3-2-我的做法-逐步拆解" aria-label="Permalink to &quot;11.3.2 我的做法（逐步拆解）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 列出目录全貌：文件总数、类型分布、命名规律</span></span>
<span class="line"><span>② 生成&quot;整理计划表&quot;：</span></span>
<span class="line"><span>   源文件 → 目标位置（每个文件的去向你都看得见）</span></span>
<span class="line"><span>③ 标注潜在冲突（重名、目标目录已存在同名）</span></span>
<span class="line"><span>④ 你确认计划 → 执行移动</span></span>
<span class="line"><span>⑤ 输出变更日志（哪些文件去了哪里）→ 可回退</span></span></code></pre></div><h3 id="_11-3-3-为什么必须-先出计划" tabindex="-1">11.3.3 为什么必须&quot;先出计划&quot; <a class="header-anchor" href="#_11-3-3-为什么必须-先出计划" aria-label="Permalink to &quot;11.3.3 为什么必须&quot;先出计划&quot;&quot;">​</a></h3><p><strong>整理是不可逆操作（移动后路径就变了），出计划 = 给后悔留一条路。</strong></p><ul><li>计划阶段发现问题：改一行计划即可；</li><li>执行后发现问题：路径全变了，找回来很痛苦。</li></ul><h2 id="_11-4-批量处理-安全第一" tabindex="-1">11.4 批量处理：安全第一 <a class="header-anchor" href="#_11-4-批量处理-安全第一" aria-label="Permalink to &quot;11.4 批量处理：安全第一&quot;">​</a></h2><p>批量操作最容易出事，所以规矩更多：</p><table tabindex="0"><thead><tr><th>规矩</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>先统计后动手</strong></td><td>先说清规模</td><td>&quot;共有 342 个文件要移动&quot;</td></tr><tr><td><strong>先试运行</strong></td><td>能模拟就先模拟</td><td>干跑模式、-WhatIf</td></tr><tr><td><strong>保留日志</strong></td><td>每步有记录，可撤销</td><td>输出变更日志文件</td></tr><tr><td><strong>不可逆操作前必须确认</strong></td><td>删除、覆盖、改名冲突</td><td>逐项列出再问</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">批量操作三问</p><p>执行任何批量操作前，先过三问：</p><ol><li>影响多少个文件？（数量）</li><li>操作可逆吗？（删除/覆盖 = 不可逆）</li><li>出错怎么回退？（日志/备份）</li></ol></div><h2 id="_11-5-内容搜索的进阶用法" tabindex="-1">11.5 内容搜索的进阶用法 <a class="header-anchor" href="#_11-5-内容搜索的进阶用法" aria-label="Permalink to &quot;11.5 内容搜索的进阶用法&quot;">​</a></h2><p>Grep 不只是&quot;搜关键词&quot;，它支持正则表达式和组合条件：</p><table tabindex="0"><thead><tr><th>用法</th><th>示例</th><th>效果</th></tr></thead><tbody><tr><td>正则表达式</td><td><code>err.*\\d{4}</code></td><td>匹配 err 后跟 4 位数字</td></tr><tr><td>大小写不敏感</td><td>搜 <code>readme</code></td><td>同时匹配 README/ReadMe</td></tr><tr><td>限定文件类型</td><td>只在 <code>*.rs</code>、<code>*.md</code> 里搜</td><td>缩小范围</td></tr><tr><td>多模式组合</td><td>一次搜多个模式</td><td>同时找 TODO 和 FIXME</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>例：在 src/ 里搜所有包含 &quot;TODO&quot; 或 &quot;FIXME&quot; 的代码行</span></span></code></pre></div><h3 id="_11-5-1-搜索策略" tabindex="-1">11.5.1 搜索策略 <a class="header-anchor" href="#_11-5-1-搜索策略" aria-label="Permalink to &quot;11.5.1 搜索策略&quot;">​</a></h3><ol><li><strong>从宽到窄</strong>：先全局搜，再按文件类型、目录缩小；</li><li><strong>关键词要多备几个</strong>：同义词、缩写、大小写变体；</li><li><strong>搜不到 ≠ 不存在</strong>：可能编码问题或关键词不对，换个说法再试。</li></ol><h2 id="_11-6-文件任务的完整流程模板" tabindex="-1">11.6 文件任务的完整流程模板 <a class="header-anchor" href="#_11-6-文件任务的完整流程模板" aria-label="Permalink to &quot;11.6 文件任务的完整流程模板&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 盘点：Glob/列目录 → 搞清楚有什么</span></span>
<span class="line"><span>② 规划：整理计划 / 处理方案（给你确认）</span></span>
<span class="line"><span>③ 试运行：能模拟先模拟，列清单</span></span>
<span class="line"><span>④ 执行：动手（留日志）</span></span>
<span class="line"><span>⑤ 验证：抽查结果，确认符合预期</span></span>
<span class="line"><span>⑥ 汇报：改了什么、去哪了、有无异常</span></span></code></pre></div><p><strong>六步走完，文件任务稳如老狗。</strong></p><h2 id="_11-7-练习" tabindex="-1">11.7 练习 <a class="header-anchor" href="#_11-7-练习" aria-label="Permalink to &quot;11.7 练习&quot;">​</a></h2><ol><li>让我用 Glob 列出某个目录下的全部文件，按类型统计；</li><li>给我一个真实的整理需求，要求&quot;先出计划再执行&quot;；</li><li>用 Grep 搜一个你关心的关键词（正则或大小写不敏感），看看发现；</li><li>走一遍完整六步流程：盘点 → 规划 → 试运行 → 执行 → 验证 → 汇报。</li></ol><hr><blockquote><p>小结：文件任务的精髓是**&quot;先看清楚，再动手，动完留痕&quot;**。批量操作不怕慢，就怕不可逆——先统计、先试运行、留日志、要确认，四道保险缺一不可。下一章：数据与表格。</p></blockquote>`,39)])])}const b=a(n,[["render",o]]);export{u as __pageData,b as default};
